const DICTS = { en, de, zh, ru, hi };

let current = "en";

export function setUiLang(id) {
  current = DICTS[id] ? id : "en";
  return current;
}

export function uiLang() {
  return current;
}

export function detectUiLang() {
  const prefs = navigator.languages && navigator.languages.length ? navigator.languages : [navigator.language || "en"];
  for (const l of prefs) {
    const code = String(l).slice(0, 2).toLowerCase();
    if (DICTS[code]) return code;
  }
  return "en";
}

export function t(key, vars = {}) {
  const s = DICTS[current][key] ?? en[key] ?? key;
  return s.replace(/\{(\w+)\}/g, (_, k) => (vars[k] ?? `{${k}}`));
}

// Every language must have every key; checked by the test suite.
export function missingKeys() {
  const out = {};
  for (const [id, d] of Object.entries(DICTS)) {
    const miss = Object.keys(en).filter((k) => !(k in d));
    if (miss.length) out[id] = miss;
  }
  return out;
}
